CREATE TABLE public.campaign_representation_sessions(actor uuid PRIMARY KEY,player_id uuid NOT NULL REFERENCES public.campaign_players(id),expires_at timestamptz NOT NULL,started_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.campaign_representation_sessions TO authenticated; GRANT ALL ON public.campaign_representation_sessions TO service_role;
ALTER TABLE public.campaign_representation_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY representation_actor_read ON public.campaign_representation_sessions FOR SELECT TO authenticated USING(actor=auth.uid() AND public.is_campaign_admin());
ALTER TABLE public.campaign_letters ADD COLUMN administrative_actor uuid;
ALTER TABLE public.letter_replies ADD COLUMN administrative_actor uuid;
CREATE FUNCTION public.start_campaign_representation(p_player uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_campaign_admin() THEN RAISE EXCEPTION 'Acesso restrito ao Narrador'; END IF; IF NOT EXISTS(SELECT 1 FROM public.campaign_players WHERE id=p_player AND active AND user_id IS NOT NULL AND NOT require_password_change) THEN RAISE EXCEPTION 'Jogador inativo ou não autorizado'; END IF; IF EXISTS(SELECT 1 FROM public.campaign_players p JOIN public.user_roles r ON r.user_id=p.user_id WHERE p.id=p_player AND r.role='admin') THEN RAISE EXCEPTION 'Não representar outra conta administrativa'; END IF; INSERT INTO public.campaign_representation_sessions(actor,player_id,expires_at) VALUES(auth.uid(),p_player,now()+interval '30 minutes') ON CONFLICT(actor) DO UPDATE SET player_id=excluded.player_id,expires_at=excluded.expires_at,started_at=now(); INSERT INTO public.campaign_admin_audit(actor,target_player,action) VALUES(auth.uid(),p_player,'representation_start'); END $$;
CREATE FUNCTION public.stop_campaign_representation() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_campaign_admin() THEN RAISE EXCEPTION 'Acesso restrito ao Narrador'; END IF; INSERT INTO public.campaign_admin_audit(actor,target_player,action) SELECT actor,player_id,'representation_stop' FROM public.campaign_representation_sessions WHERE actor=auth.uid(); DELETE FROM public.campaign_representation_sessions WHERE actor=auth.uid(); END $$;
CREATE FUNCTION public.campaign_representation_action(p_action text,p_args jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE actor_id uuid:=auth.uid();p public.campaign_players;claims text:=current_setting('request.jwt.claims',true);result jsonb;rid uuid; BEGIN IF NOT public.is_campaign_admin() THEN RAISE EXCEPTION 'Acesso restrito ao Narrador'; END IF; SELECT player.* INTO p FROM public.campaign_representation_sessions s JOIN public.campaign_players player ON player.id=s.player_id WHERE s.actor=actor_id AND s.expires_at>now() AND player.active AND NOT player.require_password_change; IF NOT FOUND OR p.user_id IS NULL THEN RAISE EXCEPTION 'Representação expirada ou jogador inativo'; END IF; PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',p.user_id,'role','authenticated')::text,true);
IF p_action='read' THEN result:=jsonb_build_object('player',to_jsonb(p),'houses',(SELECT coalesce(jsonb_agg(to_jsonb(h)),'[]') FROM public.campaign_houses h WHERE public.in_campaign_house(h.id)),'records',(SELECT coalesce(jsonb_agg(to_jsonb(r)),'[]') FROM public.campaign_records r WHERE public.can_read_record(r)),'letters',(SELECT coalesce(jsonb_agg(to_jsonb(l)),'[]') FROM public.campaign_letters l WHERE public.can_read_letter(l)),'replies',(SELECT coalesce(jsonb_agg(to_jsonb(r)),'[]') FROM public.letter_replies r WHERE public.can_read_reply(r)),'week',public.open_letter_round());
ELSIF p_action='save_record' THEN result:=public.save_campaign_record((p_args->>'id')::uuid,(p_args->>'version')::integer,p_args->>'title',p_args->>'content');
ELSIF p_action='send' THEN rid:=public.player_send_letter_to(p_args->>'subject',p_args->>'content',nullif(p_args->>'house',''),(p_args->>'key')::uuid); UPDATE public.campaign_letters SET administrative_actor=actor_id WHERE id=rid; result:=jsonb_build_object('id',rid);
ELSIF p_action='reply' THEN rid:=public.reply_weekly_message((p_args->>'letter')::uuid,nullif(p_args->>'reply','')::uuid,p_args->>'content',(p_args->>'key')::uuid,false); UPDATE public.letter_replies SET administrative_actor=actor_id WHERE id=rid; DELETE FROM public.letter_receipts WHERE letter_id=(p_args->>'letter')::uuid AND user_id=p.user_id AND read_at>=now(); result:=jsonb_build_object('id',rid);
ELSIF p_action='draft' THEN rid:=public.save_letter_draft((p_args->>'key')::uuid,nullif(p_args->>'house',''),p_args->>'subject',p_args->>'content',public.open_letter_round()); UPDATE public.campaign_letters SET administrative_actor=actor_id WHERE id=rid; result:=jsonb_build_object('id',rid);
ELSIF p_action='delete' THEN PERFORM public.delete_campaign_letter((p_args->>'id')::uuid); result:='{}';
ELSE RAISE EXCEPTION 'Action non autorisée'; END IF;
PERFORM set_config('request.jwt.claims',coalesce(claims,''),true); IF p_action<>'read' THEN INSERT INTO public.campaign_admin_audit(actor,target_player,action,details) VALUES(actor_id,p.id,'representation_'||p_action,jsonb_build_object('entity',coalesce(p_args->>'id',p_args->>'letter',result->>'id'))); END IF; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.start_campaign_representation(uuid),public.stop_campaign_representation(),public.campaign_representation_action(text,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.start_campaign_representation(uuid),public.stop_campaign_representation(),public.campaign_representation_action(text,jsonb) TO authenticated;